    s.add(labels[i] >= 0, labels[i] <= 27)
s.add(Distinct(labels))
diffs = []
for g in range(5):
    offs = g*3
    for a,b in [(0,1),(1,2),(2,0)]:
        diffs.append(Abs(labels[offs+a] - labels[offs+b]))
for g in range(4):
    for i in range(3):
        diffs.append(Abs(labels[g*3 + i] - labels[(g+1)*3 + i]))
s.add(Distinct(diffs))
for d in diffs:
    s.add(d >=1, d<=27)
print(s.check())
if s.check() == sat:
    m = s.model()
    sol = [int(m.evaluate(labels[i]).as_long()) for i in range(15)]
    print(sol)

